import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { kineticText } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group
  const root = new Group();

  // ---------------------------------------------------------------------------
  // Backdrop plane with vertical gradient
  // ---------------------------------------------------------------------------
  const backdropGeom = new PlaneGeometry(7, 5.5);
  const gradientNode = mix(
    color(new Color('#0b0b10')),
    color(new Color('#13131a')),
    uv().y
  );
  const backdropMat = new MeshBasicNodeMaterial({
    toneMapped: true,
    nodeColor: gradientNode,
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // ---------------------------------------------------------------------------
  // Caption (small kicker) – placed above hero
  // ---------------------------------------------------------------------------
  const captionOpts = {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12,
  };
  const caption = ctx.fontAtlas.createText(
    'NOVA ATELIER / CALIBRE PROGRAM',
    captionOpts
  );
  caption.position.set(0, 1.15, 0);
  root.add(caption);

  // ---------------------------------------------------------------------------
  // Render type text from spec (if any)
  // ---------------------------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    if (item.role === 'type') {
      const typeOpts = {
        fontSize: item.typography?.fontSize ?? 34,
        color: '#16161d',
        align: 'center',
        letterSpacingPx: item.typography?.letterSpacingPx ?? 0,
      };
      const typeObj = ctx.fontAtlas.createText(item.text, typeOpts);
      typeObj.position.set(0, 0.8, 0);
      root.add(typeObj);
    }
  }

  // ---------------------------------------------------------------------------
  // Hero headline – split per word for depth parallax
  // ---------------------------------------------------------------------------
  const heroLine = 'TIME, MACHINED.';
  const heroWords = heroLine.split(' ');
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  const heroZOffsets = [0.12, -0.12];
  heroWords.forEach((word, i) => {
    const txt = ctx.fontAtlas.createText(word, {
      fontSize: 124,
      color: '#16161d',
      align: 'center',
      letterSpacingPx: -0.01,
    });
    txt.position.set(i * 0.1 - (heroWords.length - 1) * 0.05, 0, heroZOffsets[i] || 0);
    heroGroup.add(txt);
  });
  root.add(heroGroup);

  // ---------------------------------------------------------------------------
  // Accent underline under hero
  // ---------------------------------------------------------------------------
  const underlineWidth = 2.6 * 0.045;
  const underlineHeight = 0.045;
  const underlineGeom = new PlaneGeometry(underlineWidth, underlineHeight);
  const underlineMat = new MeshBasicNodeMaterial({
    toneMapped: true,
    nodeColor: color(new Color('#ff2a38')),
  });
  const underline = new Mesh(underlineGeom, underlineMat);
  underline.position.set(-underlineWidth / 2, 0.35, 0);
  underline.scale.set(0, 1, 1);
  root.add(underline);

  // ---------------------------------------------------------------------------
  // Subhead – fades up beneath hero
  // ---------------------------------------------------------------------------
  const subheadOpts = {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.02,
  };
  const subhead = ctx.fontAtlas.createText(
    'Every calibre begins as a solid billet.',
    subheadOpts
  );
  subhead.position.set(0, -0.65, 0);
  subhead.traverse((c) => {
    if (c.material) {
      c.material.transparent = true;
      c.material.opacity = 0;
    }
  });
  root.add(subhead);

  // ---------------------------------------------------------------------------
  // Cinematic primitives
  // ---------------------------------------------------------------------------
  const primitives = [];

  if (ctx.primitives && ctx.primitives['kinetic-text']) {
    const kinetic = ctx.primitives['kinetic-text'](heroGroup, {
      staggerMs: 60,
      riseUnits: 0.35,
    });
    primitives.push(kinetic);
  }

  // ---------------------------------------------------------------------------
  // GSAP timelines for additional animations
  // ---------------------------------------------------------------------------
  const timelines = [];

  const underlineTL = gsap.timeline({ paused: true });
  underlineTL.fromTo(
    underline.scale,
    { x: 0 },
    {
      x: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      delay: 0.12,
    }
  );
  timelines.push(underlineTL);

  const subheadTL = gsap.timeline({ paused: true });
  subheadTL.fromTo(
    subhead,
    { opacity: 0, y: 0.2 },
    {
      opacity: 1,
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }
  );
  timelines.push(subheadTL);

  const masterTL = gsap.timeline();
  if (primitives.length && primitives[0].timeline) {
    masterTL.add(primitives[0].timeline);
  }
  masterTL.add(underlineTL, '+=0.12');
  masterTL.add(subheadTL, '+=0.0');
  masterTL.play();

  // ---------------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    backdropGeom.dispose();
    backdropMat.dispose();
    underlineGeom.dispose();
    underlineMat.dispose();

    root.traverse((obj) => {
      if (obj.isMesh && obj.geometry && obj.geometry.dispose) {
        obj.geometry.dispose();
      }
      if (obj.material && obj.material.dispose) {
        obj.material.dispose();
      }
    });

    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });

    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') tl.kill();
    });
    if (masterTL && typeof masterTL.kill === 'function') masterTL.kill();
  };

  return root;
}
